.main-container {
	--ckeditor5-preview-sidebar-width: 270px;
	font-family: "Frutiger 45 Light";
	margin-left: auto;
	margin-right: auto;
}

.ck-content {
	/* font-size: 12px; */
	line-height: 1.6;
	word-break: break-word;
	font-family: "Frutiger 45 Light", "Segoe UI Symbol";
}

.ck-content .table thead {
	display: table-row-group;
}

.ck-content .table tr {
	break-inside: avoid;
	break-after: auto;
}

.ck-content table {
	border-collapse: collapse;
	border-spacing: 0;
	width: 100%;
	height: 100%;
	border: 1px solid #bfbfbf;
}

.ck-content table td,
.ck-content table th {
	min-width: 2em;
	padding: 0.4em;
	border: 1px solid #bfbfbf;
}

.text-version-1 {
    display: flex;
    margin-left: 39.5rem;
    margin-bottom: 3rem;
    justify-content: center;
}

.chip-version {
    display: inline-flex;
    padding: 5px 8px;
    font-weight: bold;
    border-radius: 15px;
    background-color: #e0e0e0;
    font-size: 12px;
    text-align: center;
    font-family: 'Poppins';
    align-items: center;
    justify-content: center;
    white-space: nowrap;
    min-width: fit-content;
    max-width: 100%;
    overflow: hidden;
    text-overflow: ellipsis;
}
  
.blank-space {
	height: 90px;
}

.section-header-letter{
	margin-left: -5px;
}

.table-width-full{
	width: 100%;
}

